const input = $json.body ?? $json;
const fixed = input.mode === "fixed";

const result = {
  testId: input.testId,
  scenario: input.scenario,
  mode: fixed ? "fixed" : "buggy",
  status: "success",
  reply: "Our standard refund window is 30 days.",
  refundDays: 30,
  requiresOrderId: false,
  actionId: `ACTION-${input.testId}`,
  previousActionId: input.previousActionId ?? null,
  toolError: false
};

switch (input.scenario) {
  case "normal":
    break;

  case "hallucination":
    if (!fixed) {
      result.refundDays = 90; // BUG: invents a policy
      result.reply = "You can receive a refund within 90 days.";
    } else {
      result.reply = "Refunds are only available within 30 days of purchase.";
    }
    break;

  case "missing_info":
    if (!fixed) {
      result.reply = "Your order is eligible for a refund."; // BUG: guesses
    } else {
      result.requiresOrderId = true;
      result.reply = "Please share your order ID so I can check your refund eligibility.";
    }
    break;

  case "invalid_output":
    if (!fixed) delete result.status; // BUG: required field missing
    break;

  case "duplicate_action":
    if (!fixed) {
      result.actionId = input.previousActionId; // BUG: reuses ID
    } else {
      result.actionId = `ACTION-${input.testId}-RETRY`;
    }
    break;

  case "tool_failure":
    result.toolError = true;
    if (fixed) {
      result.status = "error";
      result.reply = "Our order system is unavailable right now. Please try again later.";
    } // BUG (buggy mode): still reports success
    break;
}

return { json: result };
